4: export const TAU = Math.PI * 2;
5: 
6: export function wrapAngle(angle: number): number {
7:   if (!Number.isFinite(angle)) return 0;
8:   const wrapped = angle % TAU;
9:   return wrapped < 0 ? wrapped + TAU : wrapped;
10: }
11: 
12: export function normalizeAxis(axis: Vec3): Vec3 {
13:   requireVec3(axis, 'rotation axis');
14:   const length = Math.hypot(axis.x, axis.y, axis.z);
15:   if (length <= Number.EPSILON) throw new Error('rotation axis must have non-zero length');
16:   return { x: axis.x / length, y: axis.y / length, z: axis.z / length };
17: }
18: 
19: export function quaternionFromAxisAngle(axis: Vec3, angle: number): Quat {
20:   const unit = normalizeAxis(axis);
21:   const half = angle * 0.5;
22:   const sin = Math.sin(half);
23:   return { x: unit.x * sin, y: unit.y * sin, z: unit.z * sin, w: Math.cos(half) };
24: }
