26: export function rotateVector(rotation: Quat, vector: Vec3): Vec3 {
27:   const { x: qx, y: qy, z: qz, w: qw } = rotation;
28:   const tx = 2 * (qy * vector.z - qz * vector.y);
29:   const ty = 2 * (qz * vector.x - qx * vector.z);
30:   const tz = 2 * (qx * vector.y - qy * vector.x);
31:   return {
32:     x: vector.x + qw * tx + (qy * tz - qz * ty),
33:     y: vector.y + qw * ty + (qz * tx - qx * tz),
34:     z: vector.z + qw * tz + (qx * ty - qy * tx),
35:   };
36: }
