44: export class RotationDriver {
45:   readonly speed: number;
46:   readonly phase: number;
47:   readonly maxStepSeconds: number;
48:   private elapsedSeconds = 0;
49: 
50:   constructor(options: RotationDriverOptions) {
51:     this.speed = requireFinite(options.speed, 'rotation speed');
52:     this.phase = requireFinite(options.phase ?? 0, 'rotation phase');
53:     this.maxStepSeconds = requirePositive(options.maxStepSeconds ?? 0.1, 'max rotation step');
54:   }
55: 
56:   get elapsed(): number { return this.elapsedSeconds; }
57:   get angle(): number { return wrapAngle(this.phase + this.speed * this.elapsedSeconds); }
58: 
59:   advance(deltaSeconds: number): number {
60:     if (!Number.isFinite(deltaSeconds) || deltaSeconds <= 0) return this.angle;
61:     this.elapsedSeconds += Math.min(deltaSeconds, this.maxStepSeconds);
62:     return this.angle;
63:   }
64: 
65:   setElapsed(seconds: number): number {
66:     this.elapsedSeconds = Math.max(0, requireFinite(seconds, 'elapsed rotation time'));
67:     return this.angle;
68:   }
69: 
70:   reset(): number {
71:     this.elapsedSeconds = 0;
72:     return this.angle;
